let roll = Math.ceil(CONFIG.Dice.randomUniform() * 10) 

if (roll >= 7 && args.result.fumble)
{
	args.result.text.unstable=`<strong>Unstable</strong>: The weapon explodes! It deals ${this.item.system.damage.base} to the user (Rolled ${roll}).`
}	
else if (args.result.fumble) 
    {
        args.result.text.unstable=`<strong>Unstable</strong>: Rolled ${roll}`
    }

